/**
 * Normalize a label for comparison and display: trimmed, internal whitespace
 * collapsed to one space, and lowercased.
 * @param {string} label - the raw label text.
 * @returns {string} the normalized label.
 */
export function normalizeLabel(label) {
  return label.trim().replace(/\s+/gu, ' ').toLowerCase()
}

/** A link-definition line, once its own text has been trimmed: `[label]: url`. */
export const DEFINITION = /^\[([^\]]*)\]:\s+(\S.*)$/u
"}

