{"file_path":"src/block.js","content":"/** Block parsing: fences, headings, nested lists, link definitions, and paragraphs. */

import { escapeText } from './html.js'
import { renderInline } from './inline.js'
import { DEFINITION, normalizeLabel } from './labels.js'

const FENCE = /^(`{3,})([^`]*)$/
const HEADING = /^(#{1,6}) (.*)$/
const ITEM = /^( *)- (.*)$/

/** One refusal of a document line, carrying the 1-based line it was read at. */
export class BlockError extends Error {
  /**
   * @param {number} line - the 1-based input line.
   * @param {string} message - the message the specification words, without the position.
   */
  constructor(line, message) {
    super(message)
    this.name = 'BlockError'
    this.line = line
  }
}

/**
 * Every input line, with the empty tail a trailing newline leaves dropped.
 * @param {string} text - the whole input.
 * @returns {string[]} the lines.
 */
export function splitLines(text) {
  const split = text.split('\n')
  if (split.length > 0 && split[split.length - 1] === '') split.pop()
  return split
}

/**
 * Append a bullet item to the list currently open, nesting it under the last
 * item of the level above when its indentation calls for that, and capping
 * how deep it may jump.
 * @param {object[][]} listStack - the open list's siblings at each level, index 0 first.
 * @param {number} desired - the level the item's indentation asks for.
 * @param {string} text - the item's own trimmed text.
 */
function addItem(listStack, desired, text) {
  const level = listStack.length === 0 ? 0 : Math.min(desired, listStack.length)
  if (level === listStack.length) {
    if (listStack.length > 0) {
      const parentSiblings = listStack[listStack.length - 1]
      const parent = parentSiblings[parentSiblings.length - 1]
      parent.children = []
      listStack.push(parent.children)
    } else {
      listStack.push([])
    }
  } else {
    listStack.length = level + 1
  }
  listStack[level].push({ text, children: [] })
}

/**
 * The blocks of one document, and the link definitions in force once it has been read.
 * @param {string[]} lines - the document's lines.
 * @param {Map<string, {url: string, source: string}>} [initialDefinitions] - definitions already in force before the document, keyed by normalized label.
 * @returns {{blocks: object[], definitions: Map<string, {url: string, source: string}>}} the blocks in document order, and the combined definitions.
 * @throws {BlockError} on an unterminated fence or a label defined twice.
 */
export function parse(lines, initialDefinitions = new Map()) {
  const out = []
  const definitions = new Map(initialDefinitions)
  let paragraph = []
  let listStack
  const flush = () => {
    if (paragraph.length > 0) {
      out.push({ kind: 'paragraph', lines: paragraph })
      paragraph = []
    }
    if (listStack !== undefined) {
      out.push({ kind: 'list', items: listStack[0] })
      listStack = undefined
    }
  }
  for (let index = 0; index < lines.length; index += 1) {
    const raw = lines[index]
    const line = index + 1
    const fence = FENCE.exec(raw)
    if (fence !== null) {
      flush()
      const content = []
      let close = -1
      for (let scan = index + 1; scan < lines.length; scan += 1) {
        const candidate = lines[scan].trim()
        if (/^`{3,}$/u.test(candidate) && candidate.length >= fence[1].length) {
          close = scan
          break
        }
        content.push(lines[scan])
      }
      if (close === -1) throw new BlockError(line, 'unterminated code fence')
      out.push({ kind: 'fence', info: fence[2].trim().split(/\s+/u)[0], content })
      index = close
      continue
    }
    if (raw.trim() === '') {
      flush()
      continue
    }
    const heading = HEADING.exec(raw)
    if (heading !== null) {
      flush()
      out.push({ kind: 'heading', level: heading[1].length, text: heading[2].trim() })
      continue
    }
    const definition = DEFINITION.exec(raw.trim())
    if (definition !== null) {
      flush()
      const label = normalizeLabel(definition[1])
      if (definitions.has(label)) throw new BlockError(line, `label ${label} is defined twice`)
      definitions.set(label, { url: definition[2].trim(), source: 'document' })
      continue
    }
    const item = ITEM.exec(raw)
    if (item !== null && paragraph.length === 0) {
      if (listStack === undefined) listStack = []
      addItem(listStack, Math.floor(item[1].length / 2), item[2].trim())
      continue
    }
    if (listStack !== undefined) flush()
    paragraph.push(raw.trim())
  }
  flush()
  return { blocks: out, definitions }
}

/**
 * Render one list, and the nested lists its items open, to HTML.
 * @param {readonly object[]} items - the list's items, each carrying its own children.
 * @param {ReadonlyMap<string, {url: string, source: string}>} definitions - the definitions in force.
 * @returns {string} the `<ul>` block, its lines joined by newlines.
 */
function renderList(items, definitions) {
  const lines = ['<ul>']
  for (const item of items) {
    if (item.children.length === 0) {
      lines.push(`<li>${renderInline(item.text, definitions)}</li>`)
    } else {
      lines.push(`<li>${renderInline(item.text, definitions)}`)
      lines.push(renderList(item.children, definitions))
      lines.push('</li>')
    }
  }
  lines.push('</ul>')
  return lines.join('\n')
}

/**
 * Render parsed blocks to HTML.
 * @param {readonly object[]} parsed - the document's blocks.
 * @param {ReadonlyMap<string, {url: string, source: string}>} [definitions] - the definitions in force, for reference links.
 * @returns {string} the HTML, with a trailing newline unless the document holds no block.
 */
export function render(parsed, definitions = new Map()) {
  const rendered = parsed.map((block) => {
    if (block.kind === 'heading') return `<h${block.level}>${renderInline(block.text, definitions)}</h${block.level}>`
    if (block.kind === 'paragraph') return `<p>${block.lines.map(text => renderInline(text, definitions)).join('\n')}</p>`
    if (block.kind === 'list') return renderList(block.items, definitions)
    const language = escapeText(block.info)
    const open = block.info === '' ? '<pre><code>' : `<pre><code class="language-${language}">`
    return `${open}${block.content.map(text => `${escapeText(text)}\n`).join('')}</code></pre>`
  })
  return rendered.length === 0 ? '' : `${rendered.join('\n')}\n`
}

/**
 * The headings of parsed blocks, for the outline.
 * @param {readonly object[]} parsed - the document's blocks.
 * @returns {{level: number, text: string}[]} the headings in document order.
 */
export function headings(parsed) {
  return parsed.filter(block => block.kind === 'heading').map(block => ({ level: block.level, text: block.text }))
}

/**
 * Read a definitions file: one definition per line, blank lines and `#` comments ignored.
 * @param {string} text - the file's whole content.
 * @returns {Map<string, {url: string, source: string}>} the definitions it holds, keyed by normalized label.
 * @throws {BlockError} on a line that is neither blank, a comment, nor a definition, or on a label defined twice; the line counts from 1 within this file.
 */
export function parseDefinitionsFile(text) {
  const definitions = new Map()
  const lines = splitLines(text)
  lines.forEach((raw, index) => {
    const line = index + 1
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) return
    const definition = DEFINITION.exec(trimmed)
    if (definition === null) throw new BlockError(line, 'expected [label]: <url>')
    const label = normalizeLabel(definition[1])
    if (definitions.has(label)) throw new BlockError(line, `label ${label} is defined twice`)
    definitions.set(label, { url: definition[2].trim(), source: 'file' })
  })
  return definitions
}
"}

